export function operationPath(operationId: keyof typeof OPERATION_PATHS, parameters: Record<string, string | number> = {}) {
  return OPERATION_PATHS[operationId].replace(/\{([^}]+)\}/gu, (_match, name) => {
    const value = parameters[name];
    if (value === undefined) throw new Error(`Missing contract path parameter: ${name}`);
    return encodeURIComponent(String(value));
  });
}
